<?php
require dirname(__DIR__).'/includes/bootstrap.php';require_permission('drivers.export');ensure_runtime_schema();header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="registration-counts-'.date('Y-m-d').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Date','Customers Registered','Drivers Registered','Combined']);foreach(db()->query('SELECT activity_date,customers_registered,drivers_registered FROM daily_growth_counts ORDER BY activity_date DESC') as $r)fputcsv($out,[$r['activity_date'],$r['customers_registered'],$r['drivers_registered'],(int)$r['customers_registered']+(int)$r['drivers_registered']]);fclose($out);exit;
